(1763471, 239440, 33672, '<td valign="top">Nice angle. Great subject and comp.</td>', 'Nice angle. Great subject and comp.', '2005-10-06 00:25:03.000000', NULL, 1),
(1763472, 240436, 37875, '<td valign="top">fun concept.  i''m not sure if it''s the neutrality of the background, or the full-body shot, but it feels less animated than the picture really is.  not sure why, because her expression and hands are so animated...lovely model!</td>', 'fun concept.  i''m not sure if it''s the neutrality of the background, or the full-body shot, but it feels less animated than the picture really is.  not sure why, because her expression and hands are so animated...lovely model!', '2005-10-06 00:25:36.000000', NULL, 1),
