INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1764764, 240511, 32644, '<td valign="top">Interesting shot but I don''t get the concept.</td>', 'Interesting shot but I don''t get the concept.', '2005-10-06 13:41:12.000000', NULL, 1),
(1764782, 240288, 32644, '<td valign="top">FYI - A constitutional is a walk for the benefit of health. Hmmmm, this doesn''t fit your title. Aside from that I feel you need better lighting so that this is not so much an uninteresting silhouette. I hope you keep entering these competitions - you have an interesting perspective.</td>', 'FYI - A constitutional is a walk for the benefit of health. Hmmmm, this doesn''t fit your title. Aside from that I feel you need better lighting so that this is not so much an uninteresting silhouette. I hope you keep entering these competitions - you have an interesting perspective.', '2005-10-06 13:47:12.000000', NULL, 1),
(1764790, 240539, 32644, '<td valign="top">This is a nice window shot. A polarizer would have cut down the reflection - which is the only drawback to this shot.</td>', 'This is a nice window shot. A polarizer would have cut down the reflection - which is the only drawback to this shot.', '2005-10-06 13:49:47.000000', NULL, 1),
