(1764882, 240178, 42638, '<td valign="top">Interesting picture. Would like to see more detail of the cup though, looks like it would be appealing.</td>', 'Interesting picture. Would like to see more detail of the cup though, looks like it would be appealing.', '2005-10-06 14:24:59.000000', NULL, 1),
(1764885, 240548, 42638, '<td valign="top">Interesting picture. Nice comfortable place for coffee. The lighting is a bit off for me, it seems to be casting a yellow hue over everything.</td>', 'Interesting picture. Nice comfortable place for coffee. The lighting is a bit off for me, it seems to be casting a yellow hue over everything.', '2005-10-06 14:26:03.000000', NULL, 1),
