(1764918, 240458, 42638, '<td valign="top">Interesting. You usually do find the book, smoke and cups in coffee shops. Like the "cold" clothing too. The large area of black is a bit disturbing. Maybe crop that out some to enhance the other objects.</td>', 'Interesting. You usually do find the book, smoke and cups in coffee shops. Like the "cold" clothing too. The large area of black is a bit disturbing. Maybe crop that out some to enhance the other objects.', '2005-10-06 14:33:47.000000', NULL, 1),
(1764925, 240133, 42638, '<td valign="top">Mmm...Looks delicious. I don''t like the bright area at the bottom of the slice on the right but I love all the detail otherwise.</td>', 'Mmm...Looks delicious. I don''t like the bright area at the bottom of the slice on the right but I love all the detail otherwise.', '2005-10-06 14:34:39.000000', NULL, 1),
