(1764942, 239532, 44724, '<td valign="top">cute!!!!!!!!!!!!!</td>', 'cute!!!!!!!!!!!!!', '2005-10-06 14:37:12.000000', NULL, 1),
(1764943, 239485, 42638, '<td valign="top">Now this is interesting. It took some time to figure out that you had actually turned the picture on its side (or how most people see it). That one change made it unique from some other pictures I''ve come across. Nice twist, great reflection.</td>', 'Now this is interesting. It took some time to figure out that you had actually turned the picture on its side (or how most people see it). That one change made it unique from some other pictures I''ve come across. Nice twist, great reflection.', '2005-10-06 14:37:19.000000', NULL, 1),
