(1765467, 240455, 20941, '<td valign="top">interesting object, not sure what it is, but it seems well presented</td>', 'interesting object, not sure what it is, but it seems well presented', '2005-10-06 17:32:53.000000', NULL, 1),
(1765472, 237918, 37875, '<td valign="top">i like the idea for this photo!  i would be interested in seeing how this image would look with a deeper (more visible) shadow tone and a less-bright  background.</td>', 'i like the idea for this photo!  i would be interested in seeing how this image would look with a deeper (more visible) shadow tone and a less-bright  background.', '2005-10-06 17:34:00.000000', NULL, 1),
