(1765690, 239137, 44882, '<td valign="top">Good framing, light, warm nice colors, good sharpness, nice backgroun.... :o)</td>', 'Good framing, light, warm nice colors, good sharpness, nice backgroun.... :o)', '2005-10-06 18:54:22.000000', NULL, 1),
(1765691, 240070, 40644, '<td valign="top">Very cool colors. I''m a fan.</td>', 'Very cool colors. I''m a fan.', '2005-10-06 18:54:31.000000', NULL, 1),
