(1765694, 237665, 24013, '<td valign="top">it fits that it''s blurry.  gives a discarded feel, finished with.</td>', 'it fits that it''s blurry.  gives a discarded feel, finished with.', '2005-10-06 18:56:56.000000', NULL, 1),
(1765695, 237485, 40644, '<td valign="top">I really like the idea of this photo, the color is great and the real people rock. However, the jaggies/quality are a bit too distracting.</td>', 'I really like the idea of this photo, the color is great and the real people rock. However, the jaggies/quality are a bit too distracting.', '2005-10-06 18:57:36.000000', NULL, 1),
(1765696, 240171, 24013, '<td valign="top">great fun.  lovely comp and colours.  small, still works.</td>', 'great fun.  lovely comp and colours.  small, still works.', '2005-10-06 18:57:49.000000', NULL, 1),
(1765699, 238189, 40644, '<td valign="top">Not something I would expect to see in a shop. However, I do really like the colors and the shot in general. I wish it were bigger to show more detail though.</td>', 'Not something I would expect to see in a shop. However, I do really like the colors and the shot in general. I wish it were bigger to show more detail though.', '2005-10-06 18:58:56.000000', NULL, 1);
