(1765900, 240121, 17446, '<td valign="top">nice bold colors.  8.</td>', 'nice bold colors.  8.', '2005-10-06 19:48:46.000000', NULL, 1),
(1765901, 239590, 40245, '<td valign="top">Kind of a ssssstreeeetch I think. Without title wouldn''t make connection to coffee house and even with it, the connection is tenous.</td>', 'Kind of a ssssstreeeetch I think. Without title wouldn''t make connection to coffee house and even with it, the connection is tenous.', '2005-10-06 19:48:59.000000', NULL, 1),
(1765902, 240259, 20941, '<td valign="top">if i saw this at a coffee shop I''ld Run for Cover! nice pic tho</td>', 'if i saw this at a coffee shop I''ld Run for Cover! nice pic tho', '2005-10-06 19:49:27.000000', NULL, 1),
(1765906, 240579, 17446, '<td valign="top">this is fun.  i like the contrast of mickey''s mood vs. yours.  crooked eyes too.  ha.</td>', 'this is fun.  i like the contrast of mickey''s mood vs. yours.  crooked eyes too.  ha.', '2005-10-06 19:50:27.000000', NULL, 1),
(1765909, 240585, 19978, '<td valign="top">A very busy shot that manages to capture the ambiance of a typical coffee shop. I''d suggest a tighter crop to eliminate some of the extra detail that doesn''t accentuate the main subject, the girl. Using my hands to crop out everything to the left of her right hand and below the left pinky still gives me a great shot of her (and a little tighter on her face) but eliminates the paper cubs, the label on the milk container, etc. There''s also a little bit of a red caste to her skin that seems unusual. What I like most about this shot is her face. Profile views are wonderful, and that lock of hair hanging down in her eye is a perfect expression of a hardworking caffeine jockey.</td>', 'A very busy shot that manages to capture the ambiance of a typical coffee shop. I''d suggest a tighter crop to eliminate some of the extra detail that doesn''t accentuate the main subject, the girl. Using my hands to crop out everything to the left of her right hand and below the left pinky still gives me a great shot of her (and a little tighter on her face) but eliminates the paper cubs, the label on the milk container, etc. There''s also a little bit of a red caste to her skin that seems unusual. What I like most about this shot is her face. Profile views are wonderful, and that lock of hair hanging down in her eye is a perfect expression of a hardworking caffeine jockey.', '2005-10-06 19:51:01.000000', NULL, 1),
(1765910, 239741, 17446, '<td valign="top">the swirling coffee is nice touch.</td>', 'the swirling coffee is nice touch.', '2005-10-06 19:51:18.000000', NULL, 1),
