(1771893, 240120, 29009, '<td valign="top">You''ve hit just the right note here.   I like how you''ve used the natural lines of the table to enhance the composition.  Good work!</td>', 'You''ve hit just the right note here.   I like how you''ve used the natural lines of the table to enhance the composition.  Good work!', '2005-10-09 14:27:09.000000', NULL, 1),
(1771895, 240477, 43190, '<td valign="top">please no lighting from below!  A tired technique.</td>', 'please no lighting from below!  A tired technique.', '2005-10-09 14:27:52.000000', NULL, 1),
(1771897, 240141, 43190, '<td valign="top">very contrasty, and backlit</td>', 'very contrasty, and backlit', '2005-10-09 14:29:34.000000', NULL, 1),
(1771901, 237797, 29009, '<td valign="top">You''ve got a decent composition here.  I might have put the cookies on a different colored plate so they would stand out more.  The lighting is uneven across the frame, and doesn''t seem to highlight any portion of the composition with intent.  Lastly, the tablecloth is very wrinkled which detracts from the overall visual appeal.  Overall, this is a decent shot that didn''t meet it''s potential.</td>', 'You''ve got a decent composition here.  I might have put the cookies on a different colored plate so they would stand out more.  The lighting is uneven across the frame, and doesn''t seem to highlight any portion of the composition with intent.  Lastly, the tablecloth is very wrinkled which detracts from the overall visual appeal.  Overall, this is a decent shot that didn''t meet it''s potential.', '2005-10-09 14:32:33.000000', NULL, 1),
(1771903, 240259, 29009, '<td valign="top">I''m not getting the relevance to the challenge them here, although this is a good shot.</td>', 'I''m not getting the relevance to the challenge them here, although this is a good shot.', '2005-10-09 14:33:18.000000', NULL, 1),
