INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1773869, 238114, 35804, '<td valign="top">I like this alot...it has a very mid century vibe about it...the lighting reminds me of the great old movies...very dramatic...the B &amp; W is very nice too...well done.</td>', 'I like this alot...it has a very mid century vibe about it...the lighting reminds me of the great old movies...very dramatic...the B & W is very nice too...well done.', '2005-10-10 10:55:43.000000', NULL, 1),
(1773874, 239590, 35804, '<td valign="top">I like this...I like this alot...hope people are keepin'' their minds expanded with this one...nice shot.</td>', 'I like this...I like this alot...hope people are keepin'' their minds expanded with this one...nice shot.', '2005-10-10 10:57:34.000000', NULL, 1),
(1773981, 239747, 9780, '<td valign="top">Nice lightning and wery good dof. 10<br/></td>', 'Nice lightning and wery good dof. 10', '2005-10-10 12:14:28.000000', NULL, 1),
(1773985, 240502, 9780, '<td valign="top">Nic comp but tan better sharpness could have help 7</td>', 'Nic comp but tan better sharpness could have help 7', '2005-10-10 12:15:39.000000', NULL, 1),
(1773992, 240415, 9780, '<td valign="top">Lvoly lightnig. Is it litle bit tilt? 7<br/></td>', 'Lvoly lightnig. Is it litle bit tilt? 7', '2005-10-10 12:16:54.000000', NULL, 1),
(1773995, 240178, 9780, '<td valign="top">Nice soft feeling in this pic. Only thingI see about it is that it seems like the coffe can is pushing the curtains away.</td>', 'Nice soft feeling in this pic. Only thingI see about it is that it seems like the coffe can is pushing the curtains away.', '2005-10-10 12:18:33.000000', NULL, 1),
(1774126, 240509, 43115, '<td valign="top">Good composition and crop, too bad for the legs above the woman at the top of the frame, perhaps a slightly less tight crop on the top would attach them to a body a little more (the one in the upper right corner is perfect).  Like the motion blur on the woman walking, in contrast to the people sitting still at the table.  Emotes the struggle between rushing and resting.<br/> <br/>Good conversion to B&amp;W, though color probably would have been good too...  Maybe just a hair overexposed?  (The highlights seem blown out on the cups and saucers on the table...)<br/> <br/>Nice capture.</td>', 'Good composition and crop, too bad for the legs above the woman at the top of the frame, perhaps a slightly less tight crop on the top would attach them to a body a little more (the one in the upper right corner is perfect).  Like the motion blur on the woman walking, in contrast to the people sitting still at the table.  Emotes the struggle between rushing and resting. Good conversion to B&W, though color probably would have been good too...  Maybe just a hair overexposed?  (The highlights seem blown out on the cups and saucers on the table...) Nice capture.', '2005-10-10 13:26:12.000000', NULL, 1),
(1774132, 240552, 43115, '<td valign="top">I understand this was probably an action shor at a busy coffee shop, but the grungy pitcher isn''t all that appealing.  Everything in this shot just looks grungy and dirty, and that''s not what I want to think of when I''m drinking my coffee. :(  Focus also seems a bit off, and the lighting falls off too much in the back.<br/> <br/>I think that maybe a longer exposure and some motion blur of  the hand and the pitcher would have improved this shot.</td>', 'I understand this was probably an action shor at a busy coffee shop, but the grungy pitcher isn''t all that appealing.  Everything in this shot just looks grungy and dirty, and that''s not what I want to think of when I''m drinking my coffee. :(  Focus also seems a bit off, and the lighting falls off too much in the back. I think that maybe a longer exposure and some motion blur of  the hand and the pitcher would have improved this shot.', '2005-10-10 13:28:26.000000', NULL, 1),
(1774138, 240477, 18219, '<td valign="top">A very good idea.<br/>I would have liked it better if the cup wasn''t see through.</td>', 'A very good idea.I would have liked it better if the cup wasn''t see through.', '2005-10-10 13:30:43.000000', NULL, 1),
(1774140, 240413, 43115, '<td valign="top">Looks like it was taken with a camera phone! :)  The lack of focus and horrible pixielation just doesn''t work here.  It could be an interesting scene, but I just can''t tell.  I do like the border though.</td>', 'Looks like it was taken with a camera phone! :)  The lack of focus and horrible pixielation just doesn''t work here.  It could be an interesting scene, but I just can''t tell.  I do like the border though.', '2005-10-10 13:30:53.000000', NULL, 1),
(1774142, 240566, 18219, '<td valign="top">clever pun.<br/>nice clear crisp image.</td>', 'clever pun.nice clear crisp image.', '2005-10-10 13:31:24.000000', NULL, 1),
(1774160, 239137, 43115, '<td valign="top">Initial reaction:  Interesting.  Very interesting.<br/> <br/>It''s a well set up shot.  I like the lighting, I how everyting is so similarly toned, the mug and candlestick almost blend into the table.  Very well done.  I can''t decide if the background is too distracting with the metal bars, perhaps a little less DOF to blur the background a little more?  I don''t know for sure though.  I like the crop, many would be tempted to go too tight, but the space at the left side is good.<br/> <br/>This isn''t a 10 for me, and I''m not sure quite why.  It lacks "WOW" factor, though it does have "wow" factor for me...   A good capture, and a good entry.  I think in the end brown and grey are not very exciting colors, and this photo suffers from the lack of any really exciting elements.  But from an artistic standpoint it''s very strong, and if Degas had painted it, it would have a spot in a museum.</td>', 'Initial reaction:  Interesting.  Very interesting. It''s a well set up shot.  I like the lighting, I how everyting is so similarly toned, the mug and candlestick almost blend into the table.  Very well done.  I can''t decide if the background is too distracting with the metal bars, perhaps a little less DOF to blur the background a little more?  I don''t know for sure though.  I like the crop, many would be tempted to go too tight, but the space at the left side is good. This isn''t a 10 for me, and I''m not sure quite why.  It lacks "WOW" factor, though it does have "wow" factor for me...   A good capture, and a good entry.  I think in the end brown and grey are not very exciting colors, and this photo suffers from the lack of any really exciting elements.  But from an artistic standpoint it''s very strong, and if Degas had painted it, it would have a spot in a museum.', '2005-10-10 13:39:20.000000', NULL, 1),
(1774181, 240509, 45709, '<td valign="top">whats with her leg</td>', 'whats with her leg', '2005-10-10 13:54:26.000000', NULL, 1),
(1774195, 240427, 43115, '<td valign="top">What to say, except INCREDIBLE!  The color, focus, lighting, props, everything is just perfect.  I can''t find a single thing I would change with this picture.  Great job!<br/> <br/>P.S.  Please tell us how this was done after the challenge is over. :)</td>', 'What to say, except INCREDIBLE!  The color, focus, lighting, props, everything is just perfect.  I can''t find a single thing I would change with this picture.  Great job! P.S.  Please tell us how this was done after the challenge is over. :)', '2005-10-10 14:02:45.000000', NULL, 1),
(1774197, 238189, 43115, '<td valign="top">Technically, it''s got good composition, the tight crop is nice and the shot doesn''t suffer from being smaller than most.  But the only thing in focus are the coffee beans directly below and to the right of the flower.  However, the flower is the central focal point, but it''s woefully out of focus.  Lighting and color are good though.  Bumping up one on a second look.</td>', 'Technically, it''s got good composition, the tight crop is nice and the shot doesn''t suffer from being smaller than most.  But the only thing in focus are the coffee beans directly below and to the right of the flower.  However, the flower is the central focal point, but it''s woefully out of focus.  Lighting and color are good though.  Bumping up one on a second look.', '2005-10-10 14:03:58.000000', NULL, 1),
