INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1776334, 237446, 33542, '<td valign="top">what does this have to do with the theme?</td>', 'what does this have to do with the theme?', '2005-10-11 12:26:50.000000', NULL, 1),
(1776337, 240562, 33542, '<td valign="top">this would have bene much better if the salt wasn''t blown out... maybe underexpose a bit. Also, hot spots are distracting on salt and pepper... maybe hold menu at such an angle above subject that there would not be hotspots?</td>', 'this would have bene much better if the salt wasn''t blown out... maybe underexpose a bit. Also, hot spots are distracting on salt and pepper... maybe hold menu at such an angle above subject that there would not be hotspots?', '2005-10-11 12:28:01.000000', NULL, 1),
(1776343, 239440, 33542, '<td valign="top">idea is good, but execution is not great, probably b/c of factors that weren''t your fault... i.e. hot spots on floor from lights aren''t great, but you coudn''t block or edit them out. Backing up soas to get the entire circle on floor might have been nice, but I suspect there were other distracting elements outside of the circle. Big box of cups inside kiosk is ugly, but you can''t control that. Overall, given what you had it''s a good shot. Nice focus and realistic colors.</td>', 'idea is good, but execution is not great, probably b/c of factors that weren''t your fault... i.e. hot spots on floor from lights aren''t great, but you coudn''t block or edit them out. Backing up soas to get the entire circle on floor might have been nice, but I suspect there were other distracting elements outside of the circle. Big box of cups inside kiosk is ugly, but you can''t control that. Overall, given what you had it''s a good shot. Nice focus and realistic colors.', '2005-10-11 12:31:07.000000', NULL, 1),
(1776345, 239938, 33542, '<td valign="top">very pretty, although I''d have liked it better without the white flower thing. Also, seems just a tad soft on focus, did you use USM after resizing?</td>', 'very pretty, although I''d have liked it better without the white flower thing. Also, seems just a tad soft on focus, did you use USM after resizing?', '2005-10-11 12:31:55.000000', NULL, 1),
