(1778712, 239996, 31637, '<td valign="top">Congratulations...Im so happy you ribboned...you deserve it ! there is no central subject here and thats what makes it special..just a frozen moment in time...its cropped perfectly and very clear. good choice going B &amp; W cozy looking coffee shop.</td>', 'Congratulations...Im so happy you ribboned...you deserve it ! there is no central subject here and thats what makes it special..just a frozen moment in time...its cropped perfectly and very clear. good choice going B & W cozy looking coffee shop.', '2005-10-12 05:24:43.000000', NULL, 0),
(1778730, 239996, 37893, '<td valign="top">Great candid Debbie! Great job and congrats on your ribbon!</td>', 'Great candid Debbie! Great job and congrats on your ribbon!', '2005-10-12 05:33:12.000000', NULL, 0),
(1778733, 240427, 41548, '<td valign="top">Well done on your BLUE !! You deserve it well. Pacat ca n-am votat sa-ti dau un 10 pe care-l meriti.</td>', 'Well done on your BLUE !! You deserve it well. Pacat ca n-am votat sa-ti dau un 10 pe care-l meriti.', '2005-10-12 05:38:27.000000', NULL, 0),
