(1778892, 238783, 45816, '<td valign="top">I''m imagining this photo if the focus were inverted and the cup was the spotlight with your wife blurred a bit in the background. I think her pose and expression would serve it well, it''s a wonderful picture. I like the way the photo is cropped but think seeing her hand more on the cup would have topped it off *grrr*.</td>', 'I''m imagining this photo if the focus were inverted and the cup was the spotlight with your wife blurred a bit in the background. I think her pose and expression would serve it well, it''s a wonderful picture. I like the way the photo is cropped but think seeing her hand more on the cup would have topped it off *grrr*.', '2005-10-12 07:56:43.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1778897, 240427, 8759, '<td valign="top">Congrats! <br/>Is this the 4th Romanian ribbon???<br/>Felicitari!</td>', 'Congrats! Is this the 4th Romanian ribbon???Felicitari!', '2005-10-12 08:00:18.000000', NULL, 0),
(1778900, 238736, 45816, '<td valign="top">I like the shot but I LOVE what you did with the colors- it makes me think of the 1940''s. I wish he didn''t have that darn juice sitting in front of him! For some reason I fixated on it a little.</td>', 'I like the shot but I LOVE what you did with the colors- it makes me think of the 1940''s. I wish he didn''t have that darn juice sitting in front of him! For some reason I fixated on it a little.', '2005-10-12 08:02:51.000000', NULL, 0),
(1778905, 239938, 45816, '<td valign="top">I didn''t realize the flower was a cigarette until I had begun reading through other comments. Uhg. I wonder how long I could''ve lived like that... it''s very  cool.</td>', 'I didn''t realize the flower was a cigarette until I had begun reading through other comments. Uhg. I wonder how long I could''ve lived like that... it''s very  cool.', '2005-10-12 08:08:14.000000', NULL, 0),
(1778908, 238915, 45816, '<td valign="top">I like it. It looks tastey to me and I don''t like coffee.</td>', 'I like it. It looks tastey to me and I don''t like coffee.', '2005-10-12 08:09:14.000000', NULL, 0),
(1778912, 238962, 45816, '<td valign="top">Awesome. The coffee reminds me of a croc flying up from the water to snap around its prey. Beautifully captured.</td>', 'Awesome. The coffee reminds me of a croc flying up from the water to snap around its prey. Beautifully captured.', '2005-10-12 08:12:00.000000', NULL, 0),
(1778913, 240427, 10413, '<td valign="top">Congrats Mircea on a well deserved blue. Awesome shot.</td>', 'Congrats Mircea on a well deserved blue. Awesome shot.', '2005-10-12 08:13:57.000000', NULL, 0),
(1778915, 238962, 888, '<td valign="top">Apres Results:<br/> <br/>Thanks for the comments everyone, it was great to get a score over 6.<br/> <br/>Yup, the bubble was distracting, I experimented with diferent crops but it  either meant showing more of the cup which wasn''t ideal or keeping the bottom edge of the current crop and lowering the top of the crop resulting in a squarerpicture which I just didn''t like.<br/> <br/>As for the colour, it is coffee but not being a coffee drinker I only had instant coffee which was a bit murky without milk but very reflective, the milk meant there weren''t so many reflections.</td>', 'Apres Results: Thanks for the comments everyone, it was great to get a score over 6. Yup, the bubble was distracting, I experimented with diferent crops but it  either meant showing more of the cup which wasn''t ideal or keeping the bottom edge of the current crop and lowering the top of the crop resulting in a squarerpicture which I just didn''t like. As for the colour, it is coffee but not being a coffee drinker I only had instant coffee which was a bit murky without milk but very reflective, the milk meant there weren''t so many reflections.', '2005-10-12 08:15:36.000000', NULL, 0),
(1778919, 240070, 26255, '<td valign="top">Big Congrats Doc!!!!  Great image!!!</td>', 'Big Congrats Doc!!!!  Great image!!!', '2005-10-12 08:16:24.000000', NULL, 0),
(1778920, 240348, 45816, '<td valign="top">Iii like it! The jar kind of disappears in spots with blurriness and there is unwelcome glare on it but it  is all very well placed. It''s like a still-life action shot! Oh, what the beans do when no one is looking.</td>', 'Iii like it! The jar kind of disappears in spots with blurriness and there is unwelcome glare on it but it  is all very well placed. It''s like a still-life action shot! Oh, what the beans do when no one is looking.', '2005-10-12 08:16:52.000000', NULL, 0),
(1778922, 240070, 10413, '<td valign="top">Congrats Jason on your first of many to come. This way one of my top picks.  I love the colors and lighting on this.</td>', 'Congrats Jason on your first of many to come. This way one of my top picks.  I love the colors and lighting on this.', '2005-10-12 08:18:18.000000', NULL, 0),
