(1778970, 239996, 38032, '<td valign="top">This is the first really "real" unposed captured true image I''ve seen at dpc - and it was well received.  This makes me happy.  congrats.</td>', 'This is the first really "real" unposed captured true image I''ve seen at dpc - and it was well received.  This makes me happy.  congrats.', '2005-10-12 08:50:55.000000', NULL, 0),
(1778971, 239996, 35357, '<td valign="top">Wow, congrats on your first ribbon!  Your shot makes me want to sit in that coffee shop and enjoy a cup of coffee, very nice!</td>', 'Wow, congrats on your first ribbon!  Your shot makes me want to sit in that coffee shop and enjoy a cup of coffee, very nice!', '2005-10-12 08:52:14.000000', NULL, 0),
